CREATE TABLE ${primehrSchema}.succession_continuity_plan (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, risk_review_id VARCHAR(36) NOT NULL, cycle_id VARCHAR(36) NOT NULL, designation_id VARCHAR(36) NOT NULL, charter_version_id VARCHAR(36) NOT NULL, target_type VARCHAR(20) NOT NULL, target_id BIGINT NOT NULL, job_position_id BIGINT NOT NULL, position_name VARCHAR(250) NOT NULL, plantilla_id BIGINT, plantilla_name VARCHAR(250), target_fingerprint VARCHAR(120) NOT NULL, risk_level VARCHAR(20) NOT NULL, risk_reason_snapshot VARCHAR(4000) NOT NULL, critical_functions VARCHAR(4000) NOT NULL, interim_arrangement VARCHAR(4000) NOT NULL, continuity_actions VARCHAR(4000) NOT NULL, activation_triggers VARCHAR(4000) NOT NULL, target_recovery_days INT NOT NULL, review_on DATE NOT NULL, status VARCHAR(20) NOT NULL, coverage_status VARCHAR(30) NOT NULL, bench_count INT NOT NULL, submitted_by VARCHAR(100), submitted_at DATETIMEOFFSET, approved_by VARCHAR(100), approved_at DATETIMEOFFSET, approval_reason VARCHAR(4000), finalized_by VARCHAR(100), finalized_at DATETIMEOFFSET, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_continuity_plan_risk UNIQUE(agency_id,risk_review_id), CONSTRAINT fk_succ_cont_plan_risk FOREIGN KEY(risk_review_id) REFERENCES ${primehrSchema}.succession_continuity_risk_review(id), CONSTRAINT fk_succ_cont_plan_cycle FOREIGN KEY(cycle_id) REFERENCES ${primehrSchema}.succession_cycle(id), CONSTRAINT fk_succ_cont_plan_designation FOREIGN KEY(designation_id) REFERENCES ${primehrSchema}.succession_critical_position_designation(id), CONSTRAINT fk_succ_cont_plan_charter FOREIGN KEY(charter_version_id) REFERENCES ${primehrSchema}.succession_committee_charter_version(id), CONSTRAINT ck_succ_cont_plan_status CHECK(status IN('DRAFT','SUBMITTED','APPROVED','FINALIZED')), CONSTRAINT ck_succ_cont_coverage CHECK(coverage_status IN('NOT_ASSESSED','NO_ACTIVE_BENCH','ACTIVE_BENCH')), CONSTRAINT ck_succ_cont_counts CHECK(target_recovery_days>=0 AND bench_count>=0)
);
CREATE INDEX ix_succ_continuity_position ON ${primehrSchema}.succession_continuity_plan(agency_id,designation_id,status);

CREATE TABLE ${primehrSchema}.succession_bench_coverage_entry (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, continuity_plan_id VARCHAR(36) NOT NULL, candidate_id VARCHAR(36) NOT NULL, pool_decision_id VARCHAR(36) NOT NULL, membership_event_id VARCHAR(36) NOT NULL, employee_no VARCHAR(100) NOT NULL, employee_name VARCHAR(300) NOT NULL, readiness_level_code VARCHAR(80) NOT NULL, membership_effective_on DATE NOT NULL, membership_expires_on DATE NOT NULL, development_plan_id VARCHAR(36), development_status VARCHAR(20), snapshot_at DATETIMEOFFSET NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_bench_plan_decision UNIQUE(agency_id,continuity_plan_id,pool_decision_id), CONSTRAINT fk_succ_bench_plan FOREIGN KEY(continuity_plan_id) REFERENCES ${primehrSchema}.succession_continuity_plan(id), CONSTRAINT fk_succ_bench_candidate FOREIGN KEY(candidate_id) REFERENCES ${primehrSchema}.succession_candidate(id), CONSTRAINT fk_succ_bench_decision FOREIGN KEY(pool_decision_id) REFERENCES ${primehrSchema}.succession_pool_decision(id), CONSTRAINT fk_succ_bench_membership FOREIGN KEY(membership_event_id) REFERENCES ${primehrSchema}.succession_pool_membership_event(id), CONSTRAINT fk_succ_bench_development FOREIGN KEY(development_plan_id) REFERENCES ${primehrSchema}.succession_development_plan(id), CONSTRAINT ck_succ_bench_dates CHECK(membership_expires_on>=membership_effective_on)
);
CREATE INDEX ix_succ_bench_plan ON ${primehrSchema}.succession_bench_coverage_entry(agency_id,continuity_plan_id,employee_no);

CREATE TABLE ${primehrSchema}.succession_rsp_referral_packet (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, referral_code VARCHAR(40) NOT NULL, continuity_plan_id VARCHAR(36) NOT NULL, bench_entry_id VARCHAR(36) NOT NULL, candidate_id VARCHAR(36) NOT NULL, pool_decision_id VARCHAR(36) NOT NULL, membership_event_id VARCHAR(36) NOT NULL, employee_no VARCHAR(100) NOT NULL, employee_name VARCHAR(300) NOT NULL, readiness_level_code VARCHAR(80) NOT NULL, target_job_position_id BIGINT NOT NULL, target_position_name VARCHAR(250) NOT NULL, target_plantilla_id BIGINT, target_plantilla_name VARCHAR(250), membership_expires_on DATE NOT NULL, referral_reason VARCHAR(4000) NOT NULL, employee_visible_notice VARCHAR(4000) NOT NULL, restricted_rationale VARCHAR(4000) NOT NULL, vacancy_publication_id VARCHAR(36), vacancy_request_id VARCHAR(36), vacancy_status VARCHAR(30), vacancy_record_version BIGINT, vacancy_fingerprint VARCHAR(200), vacancy_fetched_at DATETIMEOFFSET, status VARCHAR(30) NOT NULL, created_by_actor VARCHAR(100) NOT NULL, authorized_by VARCHAR(100), authorized_at DATETIMEOFFSET, sent_by VARCHAR(100), sent_at DATETIMEOFFSET, received_by VARCHAR(100), received_at DATETIMEOFFSET, status_reason VARCHAR(4000), record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_rsp_referral_code UNIQUE(agency_id,referral_code), CONSTRAINT uk_succ_rsp_referral_bench_vacancy UNIQUE(agency_id,bench_entry_id,vacancy_publication_id), CONSTRAINT fk_succ_referral_plan FOREIGN KEY(continuity_plan_id) REFERENCES ${primehrSchema}.succession_continuity_plan(id), CONSTRAINT fk_succ_referral_bench FOREIGN KEY(bench_entry_id) REFERENCES ${primehrSchema}.succession_bench_coverage_entry(id), CONSTRAINT fk_succ_referral_candidate FOREIGN KEY(candidate_id) REFERENCES ${primehrSchema}.succession_candidate(id), CONSTRAINT fk_succ_referral_decision FOREIGN KEY(pool_decision_id) REFERENCES ${primehrSchema}.succession_pool_decision(id), CONSTRAINT fk_succ_referral_membership FOREIGN KEY(membership_event_id) REFERENCES ${primehrSchema}.succession_pool_membership_event(id), CONSTRAINT ck_succ_referral_status CHECK(status IN('DRAFT','AUTHORIZED','SENT','RECEIVED','UNDER_REVIEW','CLOSED','DECLINED','WITHDRAWN'))
);
CREATE INDEX ix_succ_rsp_referral_status ON ${primehrSchema}.succession_rsp_referral_packet(agency_id,status,vacancy_publication_id);

CREATE TABLE ${primehrSchema}.succession_rsp_referral_event (
 id VARCHAR(36) PRIMARY KEY, agency_id VARCHAR(64) NOT NULL, referral_id VARCHAR(36) NOT NULL, previous_event_id VARCHAR(36), event_sequence INT NOT NULL, event_type VARCHAR(30) NOT NULL, resulting_status VARCHAR(30) NOT NULL, employee_visible_reason VARCHAR(4000) NOT NULL, restricted_reason VARCHAR(4000) NOT NULL, recorded_by VARCHAR(100) NOT NULL, recorded_at DATETIMEOFFSET NOT NULL, record_version BIGINT NOT NULL DEFAULT 0, created_by VARCHAR(100) NOT NULL, created_at DATETIMEOFFSET NOT NULL, updated_by VARCHAR(100) NOT NULL, updated_at DATETIMEOFFSET NOT NULL,
 CONSTRAINT uk_succ_rsp_referral_event_seq UNIQUE(agency_id,referral_id,event_sequence), CONSTRAINT fk_succ_ref_event_referral FOREIGN KEY(referral_id) REFERENCES ${primehrSchema}.succession_rsp_referral_packet(id), CONSTRAINT fk_succ_ref_event_previous FOREIGN KEY(previous_event_id) REFERENCES ${primehrSchema}.succession_rsp_referral_event(id), CONSTRAINT ck_succ_ref_event_sequence CHECK(event_sequence>=1)
);
CREATE INDEX ix_succ_rsp_referral_event ON ${primehrSchema}.succession_rsp_referral_event(agency_id,referral_id,event_sequence);
